     1→/**
     2→ * FreeLang Nexus - 통합 Parser
     3→ * V 모드 + Python 모드 함수를 혼합하여 파싱
     4→ */
     5→
     6→import { Token, TokenType } from '../lexer/token';
     7→import * as AST from './ast';
     8→
     9→export class NexusParser {
    10→  private tokens: Token[];
    11→  private pos: number = 0;
    12→
    13→  constructor(tokens: Token[]) {
    14→    this.tokens = tokens;
    15→  }
    16→
    17→  /**
    18→   * 파싱 진입점
    19→   */
    20→  parse(): AST.Program {
    21→    const body: Array<AST.VFunction | AST.PyFunction | AST.Statement> = [];
    22→
    23→    while (!this.isAtEnd()) {
    24→      this.skipNewlines();
    25→      if (this.isAtEnd()) break;
    26→
    27→      const token = this.peek();
    28→
    29→      // @mode 마커는 스킵 (이미 렉서에서 처리됨)
    30→      if (token.type === TokenType.MODE_MARKER) {
    31→        this.advance();
    32→        continue;
    33→      }
    34→
    35→      // 탑레벨 아이템 파싱
    36→      const item = this.parseTopLevel();
    37→      if (item) {
    38→        body.push(item);
    39→      }
    40→    }
    41→
    42→    return { type: 'Program', body };
    43→  }
    44→
    45→  /**
    46→   * 탑레벨 아이템 파싱
    47→   * V 함수, Python 함수, 또는 문장
    48→   */
    49→  private parseTopLevel(): AST.VFunction | AST.PyFunction | AST.Statement | null {
    50→    const token = this.peek();
    51→
    52→    // V 모드 함수
    53→    if (token.type === TokenType.FN) {
    54→      return this.parseVFunction();
    55→    }
    56→
    57→    // Python 모드 함수
    58→    if (token.type === TokenType.DEF) {
    59→      return this.parsePyFunction();
    60→    }
    61→
    62→    // 그 외: 문장
    63→    return this.parseStatement();
    64→  }
    65→
    66→  /**
    67→   * V 함수 파싱
    68→   * fn name(params) -> type { body }
    69→   */
    70→  private parseVFunction(): AST.VFunction {
    71→    const startToken = this.consume(TokenType.FN, 'fn 키워드 필요');
    72→    const nameToken = this.consume(TokenType.IDENTIFIER, '함수명 필요');
    73→    const name = nameToken.value;
    74→
    75→    this.consume(TokenType.LPAREN, '( 필요');
    76→    const params = this.parseVParams();
    77→    this.consume(TokenType.RPAREN, ') 필요');
    78→
    79→    const returnType = this.parseReturnType();
    80→
    81→    this.consume(TokenType.LBRACE, '{ 필요');
    82→    const body = this.parseVBlock();
    83→    this.consume(TokenType.RBRACE, '} 필요');
    84→
    85→    return {
    86→      type: 'VFunction',
    87→      name,
    88→      params,
    89→      returnType,
    90→      body,
    91→      mode: 'v',
    92→      line: startToken.line,
    93→      column: startToken.column,
    94→    };
    95→  }
    96→
    97→  /**
    98→   * Python 함수 파싱
    99→   * def name(params): INDENT body DEDENT
   100→   */
   101→  private parsePyFunction(): AST.PyFunction {
   102→    const startToken = this.consume(TokenType.DEF, 'def 키워드 필요');
   103→    const nameToken = this.consume(TokenType.IDENTIFIER, '함수명 필요');
   104→    const name = nameToken.value;
   105→
   106→    this.consume(TokenType.LPAREN, '( 필요');
   107→    const params = this.parsePyParams();
   108→    this.consume(TokenType.RPAREN, ') 필요');
   109→
   110→    const returnType = this.parseReturnType();
   111→
   112→    this.consume(TokenType.COLON, ': 필요');
   113→    this.skipNewlines();
   114→
   115→    const body = this.parsePyBlock();
   116→
   117→    return {
   118→      type: 'PyFunction',
   119→      name,
   120→      params,
   121→      returnType,
   122→      body,
   123→      mode: 'python',
   124→      line: startToken.line,
   125→      column: startToken.column,
   126→    };
   127→  }
   128→
   129→  /**
   130→   * V 함수 파라미터 파싱
   131→   * (x: i64, y: i64)
   132→   */
   133→  private parseVParams(): AST.Parameter[] {
   134→    const params: AST.Parameter[] = [];
   135→
   136→    while (!this.check(TokenType.RPAREN) && !this.isAtEnd()) {
   137→      const nameToken = this.consume(TokenType.IDENTIFIER, '파라미터명 필요');
   138→      this.consume(TokenType.COLON, ': 필요');
   139→      const typeToken = this.peek();
   140→      const typeAnnotation = this.parseType();
   141→
   142→      params.push({
   143→        name: nameToken.value,
   144→        typeAnnotation,
   145→        line: nameToken.line,
   146→        column: nameToken.column,
   147→      });
   148→
   149→      if (!this.check(TokenType.RPAREN)) {
   150→        this.consume(TokenType.COMMA, ', 필요');
   151→      }
   152→    }
   153→
   154→    return params;
   155→  }
   156→
   157→  /**
   158→   * Python 함수 파라미터 파싱
   159→   * (x, y) 또는 (x: int, y: int)
   160→   */
   161→  private parsePyParams(): AST.Parameter[] {
   162→    const params: AST.Parameter[] = [];
   163→
   164→    while (!this.check(TokenType.RPAREN) && !this.isAtEnd()) {
   165→      const nameToken = this.consume(TokenType.IDENTIFIER, '파라미터명 필요');
   166→      let typeAnnotation: string | undefined;
   167→
   168→      // 타입 어노테이션 (선택)
   169→      if (this.check(TokenType.COLON)) {
   170→        this.advance();
   171→        typeAnnotation = this.parseType();
   172→      }
   173→
   174→      params.push({
   175→        name: nameToken.value,
   176→        typeAnnotation,
   177→        line: nameToken.line,
   178→        column: nameToken.column,
   179→      });
   180→
   181→      if (!this.check(TokenType.RPAREN)) {
   182→        this.consume(TokenType.COMMA, ', 필요');
   183→      }
   184→    }
   185→
   186→    return params;
   187→  }
   188→
   189→  /**
   190→   * 반환 타입 파싱
   191→   * -> i64 (선택)
   192→   */
   193→  private parseReturnType(): string | undefined {
   194→    if (this.match(TokenType.ARROW)) {
   195→      return this.parseType();
   196→    }
   197→    return undefined;
   198→  }
   199→
   200→  /**
   201→   * 타입 파싱
   202→   * i64, string, bool 등
   203→   */
   204→  private parseType(): string {
   205→    const token = this.peek();
   206→
   207→    // 기본 타입
   208→    if (
   209→      token.type === TokenType.I64 ||
   210→      token.type === TokenType.I32 ||
   211→      token.type === TokenType.F64 ||
   212→      token.type === TokenType.BOOL ||
   213→      token.type === TokenType.STRING ||
   214→      token.type === TokenType.IDENTIFIER
   215→    ) {
   216→      return this.advance().value;
   217→    }
   218→
   219→    throw new Error(`타입 필요 at line ${token.line}`);
   220→  }
   221→
   222→  /**
   223→   * V 블록 파싱
   224→   * { statements }
   225→   */
   226→  private parseVBlock(): AST.Statement[] {
   227→    const statements: AST.Statement[] = [];
   228→
   229→    while (!this.check(TokenType.RBRACE) && !this.isAtEnd()) {
   230→      this.skipNewlines();
   231→
   232→      if (this.check(TokenType.RBRACE)) break;
   233→
   234→      const stmt = this.parseStatement();
   235→      if (stmt) {
   236→        statements.push(stmt);
   237→      }
   238→
   239→      this.skipNewlines();
   240→    }
   241→
   242→    return statements;
   243→  }
   244→
   245→  /**
   246→   * Python 블록 파싱
   247→   * INDENT statements DEDENT
   248→   */
   249→  private parsePyBlock(): AST.Statement[] {
   250→    const statements: AST.Statement[] = [];
   251→
   252→    this.consume(TokenType.INDENT, 'INDENT 필요');
   253→
   254→    while (!this.check(TokenType.DEDENT) && !this.isAtEnd()) {
   255→      this.skipNewlines();
   256→
   257→      if (this.check(TokenType.DEDENT) || this.isAtEnd()) break;
   258→
   259→      const stmt = this.parseStatement();
   260→      if (stmt) {
   261→        statements.push(stmt);
   262→      }
   263→
   264→      this.skipNewlines();
   265→    }
   266→
   267→    // DEDENT 또는 EOF 모두 허용 (파일 끝에서 DEDENT가 항상 생성되지 않을 수 있음)
   268→    if (this.check(TokenType.DEDENT)) {
   269→      this.advance();
   270→    }
   271→
   272→    return statements;
   273→  }
   274→
   275→  /**
   276→   * 문장 파싱
   277→   */
   278→  private parseStatement(): AST.Statement {
   279→    const token = this.peek();
   280→
   281→    // return 문장
   282→    if (token.type === TokenType.RETURN) {
   283→      return this.parseReturnStatement();
   284→    }
   285→
   286→    // pass 문장 (Python)
   287→    if (token.type === TokenType.PASS) {
   288→      const passToken = this.advance();
   289→      return {
   290→        type: 'ExprStatement',
   291→        expression: {
   292→          type: 'Identifier',
   293→          name: 'pass',
   294→          line: passToken.line,
   295→          column: passToken.column,
   296→          mode: passToken.mode,
   297→        },
   298→        line: passToken.line,
   299→        column: passToken.column,
   300→        mode: passToken.mode,
   301→      };
   302→    }
   303→
   304→    // let 또는 식별자 (할당 가능성)
   305→    if (token.type === TokenType.LET || token.type === TokenType.IDENTIFIER) {
   306→      return this.parseAssignOrExpr();
   307→    }
   308→
   309→    // 기본값: 표현식 문장
   310→    const expr = this.parseExpression();
   311→    const startToken = this.peek();
   312→    return {
   313→      type: 'ExprStatement',
   314→      expression: expr,
   315→      line: startToken.line,
   316→      column: startToken.column,
   317→      mode: startToken.mode,
   318→    };
   319→  }
   320→
   321→  /**
   322→   * Return 문장 파싱
   323→   */
   324→  private parseReturnStatement(): AST.ReturnStatement {
   325→    const startToken = this.consume(TokenType.RETURN, 'return 필요');
   326→    let value: AST.Expression | undefined;
   327→
   328→    // 반환값이 있으면 파싱
   329→    if (!this.check(TokenType.NEWLINE) && !this.check(TokenType.DEDENT) && !this.check(TokenType.RBRACE)) {
   330→      value = this.parseExpression();
   331→    }
   332→
   333→    return {
   334→      type: 'Return',
   335→      value,
   336→      line: startToken.line,
   337→      column: startToken.column,
   338→      mode: startToken.mode,
   339→    };
   340→  }
   341→
   342→  /**
   343→   * 할당 또는 표현식 파싱
   344→   */
   345→  private parseAssignOrExpr(): AST.Statement {
   346→    const startToken = this.peek();
   347→
   348→    // let x = value
   349→    if (startToken.type === TokenType.LET) {
   350→      this.advance();
   351→      const nameToken = this.consume(TokenType.IDENTIFIER, '변수명 필요');
   352→      this.consume(TokenType.EQUAL, '= 필요');
   353→      const value = this.parseExpression();
   354→
   355→      return {
   356→        type: 'Assign',
   357→        name: nameToken.value,
   358→        value,
   359→        line: startToken.line,
   360→        column: startToken.column,
   361→        mode: startToken.mode,
   362→      };
   363→    }
   364→
   365→    // x = value
   366→    if (startToken.type === TokenType.IDENTIFIER) {
   367→      const nameToken = this.peek();
   368→      const name = nameToken.value;
   369→      this.advance();
   370→
   371→      if (this.check(TokenType.EQUAL)) {
   372→        this.advance();
   373→        const value = this.parseExpression();
   374→
   375→        return {
   376→          type: 'Assign',
   377→          name,
   378→          value,
   379→          line: startToken.line,
   380→          column: startToken.column,
   381→          mode: startToken.mode,
   382→        };
   383→      }
   384→
   385→      // 아니면 식별자는 표현식으로 처리
   386→      const expr: AST.Identifier = {
   387→        type: 'Identifier',
   388→        name,
   389→        line: nameToken.line,
   390→        column: nameToken.column,
   391→        mode: nameToken.mode,
   392→      };
   393→
   394→      return {
   395→        type: 'ExprStatement',
   396→        expression: expr,
   397→        line: startToken.line,
   398→        column: startToken.column,
   399→        mode: startToken.mode,
   400→      };
   401→    }
   402→
   403→    throw new Error(`예상치 못한 토큰 at line ${startToken.line}`);
   404→  }
   405→
   406→  /**
   407→   * 표현식 파싱
   408→   * 간단한 구현: 곱셈/나눗셈 → 덧셈/뺄셈 → 비교/논리
   409→   */
   410→  private parseExpression(): AST.Expression {
   411→    return this.parseLogicalOr();
   412→  }
   413→
   414→  /**
   415→   * 논리 OR 파싱: ||
   416→   */
   417→  private parseLogicalOr(): AST.Expression {
   418→    let expr = this.parseLogicalAnd();
   419→
   420→    while (this.match(TokenType.OR)) {
   421→      const operator = this.previous().value;
   422→      const right = this.parseLogicalAnd();
   423→      const token = this.previous();
   424→      expr = {
   425→        type: 'BinaryExpr',
   426→        left: expr,
   427→        operator,
   428→        right,
   429→        line: token.line,
   430→        column: token.column,
   431→        mode: token.mode,
   432→      };
   433→    }
   434→
   435→    return expr;
   436→  }
   437→
   438→  /**
   439→   * 논리 AND 파싱: &&
   440→   */
   441→  private parseLogicalAnd(): AST.Expression {
   442→    let expr = this.parseEquality();
   443→
   444→    while (this.match(TokenType.AND)) {
   445→      const operator = this.previous().value;
   446→      const right = this.parseEquality();
   447→      const token = this.previous();
   448→      expr = {
   449→        type: 'BinaryExpr',
   450→        left: expr,
   451→        operator,
   452→        right,
   453→        line: token.line,
   454→        column: token.column,
   455→        mode: token.mode,
   456→      };
   457→    }
   458→
   459→    return expr;
   460→  }
   461→
   462→  /**
   463→   * 등호/부등호 파싱: ==, !=
   464→   */
   465→  private parseEquality(): AST.Expression {
   466→    let expr = this.parseComparison();
   467→
   468→    while (this.match(TokenType.EQ, TokenType.NE)) {
   469→      const operator = this.previous().value;
   470→      const right = this.parseComparison();
   471→      const token = this.previous();
   472→      expr = {
   473→        type: 'BinaryExpr',
   474→        left: expr,
   475→        operator,
   476→        right,
   477→        line: token.line,
   478→        column: token.column,
   479→        mode: token.mode,
   480→      };
   481→    }
   482→
   483→    return expr;
   484→  }
   485→
   486→  /**
   487→   * 비교 파싱: <, >, <=, >=
   488→   */
   489→  private parseComparison(): AST.Expression {
   490→    let expr = this.parseAddition();
   491→
   492→    while (this.match(TokenType.LT, TokenType.GT, TokenType.LE, TokenType.GE)) {
   493→      const operator = this.previous().value;
   494→      const right = this.parseAddition();
   495→      const token = this.previous();
   496→      expr = {
   497→        type: 'BinaryExpr',
   498→        left: expr,
   499→        operator,
   500→        right,
   501→        line: token.line,
   502→        column: token.column,
   503→        mode: token.mode,
   504→      };
   505→    }
   506→
   507→    return expr;
   508→  }
   509→
   510→  /**
   511→   * 덧셈/뺄셈 파싱
   512→   */
   513→  private parseAddition(): AST.Expression {
   514→    let expr = this.parseMultiplication();
   515→
   516→    while (this.match(TokenType.PLUS, TokenType.MINUS)) {
   517→      const operator = this.previous().value;
   518→      const right = this.parseMultiplication();
   519→      const token = this.previous();
   520→      expr = {
   521→        type: 'BinaryExpr',
   522→        left: expr,
   523→        operator,
   524→        right,
   525→        line: token.line,
   526→        column: token.column,
   527→        mode: token.mode,
   528→      };
   529→    }
   530→
   531→    return expr;
   532→  }
   533→
   534→  /**
   535→   * 곱셈/나눗셈 파싱
   536→   */
   537→  private parseMultiplication(): AST.Expression {
   538→    let expr = this.parseUnary();
   539→
   540→    while (this.match(TokenType.STAR, TokenType.SLASH)) {
   541→      const operator = this.previous().value;
   542→      const right = this.parseUnary();
   543→      const token = this.previous();
   544→      expr = {
   545→        type: 'BinaryExpr',
   546→        left: expr,
   547→        operator,
   548→        right,
   549→        line: token.line,
   550→        column: token.column,
   551→        mode: token.mode,
   552→      };
   553→    }
   554→
   555→    return expr;
   556→  }
   557→
   558→  /**
   559→   * 단항 연산 파싱
   560→   */
   561→  private parseUnary(): AST.Expression {
   562→    // TODO: 단항 연산자 (-, !, ~) 처리 가능
   563→    return this.parsePostfix();
   564→  }
   565→
   566→  /**
   567→   * 후위 연산 파싱 (함수 호출, 멤버 접근)
   568→   */
   569→  private parsePostfix(): AST.Expression {
   570→    let expr = this.parsePrimary();
   571→
   572→    while (true) {
   573→      // 함수 호출: foo()
   574→      if (this.match(TokenType.LPAREN)) {
   575→        const args = this.parseArguments();
   576→        this.consume(TokenType.RPAREN, ') 필요');
   577→
   578→        const token = this.previous();
   579→        expr = {
   580→          type: 'Call',
   581→          callee: expr,
   582→          args,
   583→          line: token.line,
   584→          column: token.column,
   585→          mode: token.mode,
   586→        };
   587→      } else {
   588→        break;
   589→      }
   590→    }
   591→
   592→    return expr;
   593→  }
   594→
   595→  /**
   596→   * 기본 표현식 파싱 (리터럴, 식별자 등)
   597→   */
   598→  private parsePrimary(): AST.Expression {
   599→    const token = this.peek();
   600→
   601→    // 숫자
   602→    if (token.type === TokenType.NUMBER) {
   603→      this.advance();
   604→      return {
   605→        type: 'Number',
   606→        value: token.value,
   607→        line: token.line,
   608→        column: token.column,
   609→        mode: token.mode,
   610→      };
   611→    }
   612→
   613→    // 문자열
   614→    if (token.type === TokenType.STRING) {
   615→      this.advance();
   616→      return {
   617→        type: 'String',
   618→        value: token.value,
   619→        line: token.line,
   620→        column: token.column,
   621→        mode: token.mode,
   622→      };
   623→    }
   624→
   625→    // true, false
   626→    if (token.type === TokenType.TRUE || token.type === TokenType.FALSE) {
   627→      this.advance();
   628→      return {
   629→        type: 'Number',
   630→        value: token.type === TokenType.TRUE ? 1 : 0,
   631→        line: token.line,
   632→        column: token.column,
   633→        mode: token.mode,
   634→      };
   635→    }
   636→
   637→    // 식별자
   638→    if (token.type === TokenType.IDENTIFIER) {
   639→      this.advance();
   640→      return {
   641→        type: 'Identifier',
   642→        name: token.value,
   643→        line: token.line,
   644→        column: token.column,
   645→        mode: token.mode,
   646→      };
   647→    }
   648→
   649→    // 괄호 식
   650→    if (this.match(TokenType.LPAREN)) {
   651→      const expr = this.parseExpression();
   652→      this.consume(TokenType.RPAREN, ') 필요');
   653→      return expr;
   654→    }
   655→
   656→    throw new Error(`예상치 못한 토큰: ${token.value} at line ${token.line}`);
   657→  }
   658→
   659→  /**
   660→   * 함수 호출 인자 파싱
   661→   */
   662→  private parseArguments(): AST.Expression[] {
   663→    const args: AST.Expression[] = [];
   664→
   665→    if (!this.check(TokenType.RPAREN)) {
   666→      do {
   667→        args.push(this.parseExpression());
   668→      } while (this.match(TokenType.COMMA));
   669→    }
   670→
   671→    return args;
   672→  }
   673→
   674→  // ========== 헬퍼 메서드 ==========
   675→
   676→  private peek(): Token {
   677→    if (this.pos >= this.tokens.length) {
   678→      return this.tokens[this.tokens.length - 1]; // EOF 토큰
   679→    }
   680→    return this.tokens[this.pos];
   681→  }
   682→
   683→  private advance(): Token {
   684→    if (!this.isAtEnd()) {
   685→      this.pos++;
   686→    }
   687→    return this.previous();
   688→  }
   689→
   690→  private previous(): Token {
   691→    return this.tokens[this.pos - 1];
   692→  }
   693→
   694→  private isAtEnd(): boolean {
   695→    return this.peek().type === TokenType.EOF;
   696→  }
   697→
   698→  private check(type: TokenType): boolean {
   699→    if (this.isAtEnd()) return false;
   700→    return this.peek().type === type;
   701→  }
   702→
   703→  private match(...types: TokenType[]): boolean {
   704→    for (const type of types) {
   705→      if (this.check(type)) {
   706→        this.advance();
   707→        return true;
   708→      }
   709→    }
   710→    return false;
   711→  }
   712→
   713→  private consume(type: TokenType, message: string): Token {
   714→    if (this.check(type)) return this.advance();
   715→
   716→    const token = this.peek();
   717→    throw new Error(`${message} at line ${token.line}, got ${token.value}`);
   718→  }
   719→
   720→  private skipNewlines(): void {
   721→    while (this.match(TokenType.NEWLINE)) {
   722→      // 계속
   723→    }
   724→  }
   725→}
   726→

