     1→/**
     2→ * FreeLang Nexus - 런타임 실행기
     3→ * 생성된 C/Python 코드를 컴파일하고 실행
     4→ */
     5→
     6→import { execSync, spawnSync, SpawnSyncReturns } from 'child_process';
     7→import * as fs from 'fs';
     8→import * as path from 'path';
     9→import * as os from 'os';
    10→import { CodegenResult } from '../codegen/nexus-codegen';
    11→
    12→export interface RunResult {
    13→  cOutput: string;      // C 실행 결과 (stdout)
    14→  pythonOutput: string; // Python 실행 결과 (stdout)
    15→  errors: string[];     // 컴파일/실행 에러 목록
    16→}
    17→
    18→export class NexusRunner {
    19→  private ccCache: string | null = null;
    20→
    21→  /**
    22→   * CodegenResult 전체 실행 (C + Python 모두)
    23→   */
    24→  run(result: CodegenResult): RunResult {
    25→    const errors: string[] = [];
    26→    let cOutput = '';
    27→    let pythonOutput = '';
    28→
    29→    // C 코드 실행
    30→    if (result.c && result.c.trim()) {
    31→      try {
    32→        cOutput = this.runC(result.c);
    33→      } catch (e) {
    34→        errors.push(`C 컴파일/실행 에러: ${(e as Error).message}`);
    35→      }
    36→    }
    37→
    38→    // Python 코드 실행
    39→    if (result.python && result.python.trim()) {
    40→      try {
    41→        pythonOutput = this.runPython(result.python);
    42→      } catch (e) {
    43→        errors.push(`Python 실행 에러: ${(e as Error).message}`);
    44→      }
    45→    }
    46→
    47→    return { cOutput, pythonOutput, errors };
    48→  }
    49→
    50→  /**
    51→   * C 코드 실행
    52→   * 임시 파일 → 컴파일 → 실행 → 정리
    53→   */
    54→  runC(cCode: string): string {
    55→    const cFile = this.tmpFile('.c');
    56→    const binFile = this.tmpFile('');
    57→
    58→    try {
    59→      // C 코드를 임시 파일에 저장
    60→      fs.writeFileSync(cFile, cCode, 'utf-8');
    61→
    62→      // 컴파일 (gcc 또는 clang)
    63→      const cc = this.detectCC();
    64→      try {
    65→        execSync(`${cc} -o ${binFile} ${cFile}`, {
    66→          stdio: 'pipe',
    67→          encoding: 'utf-8',
    68→        });
    69→      } catch (e) {
    70→        throw new Error(`컴파일 실패 (${cc}): ${(e as Error).message}`);
    71→      }
    72→
    73→      // 바이너리 실행
    74→      const result: SpawnSyncReturns<string> = spawnSync(binFile, [], {
    75→        encoding: 'utf-8',
    76→        stdio: 'pipe',
    77→      });
    78→
    79→      if (result.error) {
    80→        throw new Error(`실행 실패: ${result.error.message}`);
    81→      }
    82→
    83→      return result.stdout || '';
    84→    } finally {
    85→      // 임시 파일 정리
    86→      try {
    87→        if (fs.existsSync(cFile)) fs.unlinkSync(cFile);
    88→        if (fs.existsSync(binFile)) fs.unlinkSync(binFile);
    89→      } catch (e) {
    90→        // 정리 실패는 무시
    91→      }
    92→    }
    93→  }
    94→
    95→  /**
    96→   * Python 코드 실행
    97→   * 임시 파일 → python3 실행 → 정리
    98→   */
    99→  runPython(pyCode: string): string {
   100→    const pyFile = this.tmpFile('.py');
   101→
   102→    try {
   103→      // Python 코드를 임시 파일에 저장
   104→      fs.writeFileSync(pyFile, pyCode, 'utf-8');
   105→
   106→      // python3 실행
   107→      const result: SpawnSyncReturns<string> = spawnSync('python3', [pyFile], {
   108→        encoding: 'utf-8',
   109→        stdio: 'pipe',
   110→      });
   111→
   112→      if (result.error) {
   113→        throw new Error(`Python 실행 실패: ${result.error.message}`);
   114→      }
   115→
   116→      return result.stdout || '';
   117→    } finally {
   118→      // 임시 파일 정리
   119→      try {
   120→        if (fs.existsSync(pyFile)) fs.unlinkSync(pyFile);
   121→      } catch (e) {
   122→        // 정리 실패는 무시
   123→      }
   124→    }
   125→  }
   126→
   127→  /**
   128→   * 컴파일러 감지 (gcc 또는 clang)
   129→   * Termux 환경에서는 clang을 기본으로 사용하는 경우가 많음
   130→   */
   131→  private detectCC(): string {
   132→    if (this.ccCache) {
   133→      return this.ccCache;
   134→    }
   135→
   136→    // 먼저 gcc 확인
   137→    try {
   138→      execSync('gcc --version', { stdio: 'pipe' });
   139→      this.ccCache = 'gcc';
   140→      return 'gcc';
   141→    } catch (e) {
   142→      // gcc 실패
   143→    }
   144→
   145→    // clang 확인
   146→    try {
   147→      execSync('clang --version', { stdio: 'pipe' });
   148→      this.ccCache = 'clang';
   149→      return 'clang';
   150→    } catch (e) {
   151→      // clang 실패
   152→    }
   153→
   154→    // 기본값: gcc (찾기 실패해도 시도)
   155→    this.ccCache = 'gcc';
   156→    return 'gcc';
   157→  }
   158→
   159→  /**
   160→   * 임시 파일 경로 생성
   161→   * /tmp/nexus_TIMESTAMP.ext 형식
   162→   */
   163→  private tmpFile(ext: string): string {
   164→    const timestamp = Date.now();
   165→    const random = Math.random().toString(36).substring(2, 8);
   166→    const filename = `nexus_${timestamp}_${random}${ext}`;
   167→    return path.join(os.tmpdir(), filename);
   168→  }
   169→}
