     1→#!/usr/bin/env node
     2→
     3→/**
     4→ * FreeLang Nexus CLI
     5→ * Usage:
     6→ *   nexus run <file>      - 파일 실행
     7→ *   nexus compile <file>  - 코드 생성만 (컴파일/실행 안함)
     8→ *   nexus check <file>    - 문법 검사만
     9→ */
    10→
    11→import * as fs from 'fs';
    12→import * as path from 'path';
    13→import NexusLexer from './lexer/nexus-lexer';
    14→import { NexusParser } from './parser/nexus-parser';
    15→import { NexusCodegen } from './codegen/nexus-codegen';
    16→import { NexusRunner } from './runtime/nexus-runner';
    17→
    18→function printUsage() {
    19→  console.log(`
    20→FreeLang Nexus CLI
    21→
    22→Usage:
    23→  nexus run <file>      실행: .fl 파일 실행
    24→  nexus compile <file>  컴파일: C/Python 코드만 출력
    25→  nexus check <file>    검사: 문법 검사만
    26→  nexus --version       버전 표시
    27→  nexus --help          도움말
    28→
    29→Examples:
    30→  nexus run hello.fl
    31→  nexus compile hello.fl
    32→  nexus check hello.fl
    33→`);
    34→}
    35→
    36→async function runFile(filePath: string): Promise<void> {
    37→  try {
    38→    // 파일 읽기
    39→    if (!fs.existsSync(filePath)) {
    40→      console.error(`❌ 파일을 찾을 수 없음: ${filePath}`);
    41→      process.exit(1);
    42→    }
    43→
    44→    const source = fs.readFileSync(filePath, 'utf-8');
    45→
    46→    // Lexer
    47→    const lexer = new NexusLexer(source);
    48→    const tokens = lexer.tokenize();
    49→
    50→    // Parser
    51→    const parser = new NexusParser(tokens);
    52→    const ast = parser.parse();
    53→
    54→    // CodeGen
    55→    const codegen = new NexusCodegen();
    56→    const result = codegen.generateProgram(ast);
